// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Ask Say what this server answers for a question
	// (GET /ask)
	Ask(w http.ResponseWriter, r *http.Request, params AskParams)
	// CreateDirectorySession Sign a person in through a directory
	// (POST /auth/ldap/{providerId})
	CreateDirectorySession(w http.ResponseWriter, r *http.Request, providerId string)
	// FinishOIDCSignIn Take a person back from an OpenID Connect provider
	// (GET /auth/oidc/callback)
	FinishOIDCSignIn(w http.ResponseWriter, r *http.Request, params FinishOIDCSignInParams)
	// StartOIDCSignIn Send the browser to an OpenID Connect provider to sign in
	// (GET /auth/oidc/{providerId}/start)
	StartOIDCSignIn(w http.ResponseWriter, r *http.Request, providerId string)
	// ListSignInProviders List the providers a person may sign in through
	// (GET /auth/providers)
	ListSignInProviders(w http.ResponseWriter, r *http.Request)
	// DeleteSession End the session
	// (DELETE /auth/session)
	DeleteSession(w http.ResponseWriter, r *http.Request)
	// GetSession Report who this request is authenticated as
	// (GET /auth/session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// CreateSession Exchange a token for a browser session
	// (POST /auth/session)
	CreateSession(w http.ResponseWriter, r *http.Request)
	// GetCluster Say who the members are, and how far this one has got
	// (GET /cluster)
	GetCluster(w http.ResponseWriter, r *http.Request)
	// InitCluster Start a cluster with this node as its first member
	// (POST /cluster/init)
	InitCluster(w http.ResponseWriter, r *http.Request)
	// RemoveClusterMember Take a member out of the cluster
	// (DELETE /cluster/members/{memberId})
	RemoveClusterMember(w http.ResponseWriter, r *http.Request, memberId string)
	// ListCommits List commits, newest first
	// (GET /commits)
	ListCommits(w http.ResponseWriter, r *http.Request, params ListCommitsParams)
	// GetCommit Read one commit and everything it changed
	// (GET /commits/{commitId})
	GetCommit(w http.ResponseWriter, r *http.Request, commitId string)
	// GetHealth Report whether the server is fit to answer queries
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// ListIdentityProviders List the providers people sign in through
	// (GET /identity-providers)
	ListIdentityProviders(w http.ResponseWriter, r *http.Request)
	// CreateIdentityProvider Add a provider
	// (POST /identity-providers)
	CreateIdentityProvider(w http.ResponseWriter, r *http.Request)
	// DeleteIdentityProvider Remove a provider
	// (DELETE /identity-providers/{providerId})
	DeleteIdentityProvider(w http.ResponseWriter, r *http.Request, providerId string)
	// GetIdentityProvider Read one provider
	// (GET /identity-providers/{providerId})
	GetIdentityProvider(w http.ResponseWriter, r *http.Request, providerId string)
	// UpdateIdentityProvider Replace what a provider says about itself
	// (PUT /identity-providers/{providerId})
	UpdateIdentityProvider(w http.ResponseWriter, r *http.Request, providerId string)
	// GetMetrics Export the current metrics
	// (GET /metrics)
	GetMetrics(w http.ResponseWriter, r *http.Request)
	// StreamQueries Watch queries as they are answered
	// (GET /queries/stream)
	StreamQueries(w http.ResponseWriter, r *http.Request, params StreamQueriesParams)
	// DeleteRecord Delete a record
	// (DELETE /records/{recordId})
	DeleteRecord(w http.ResponseWriter, r *http.Request, recordId RecordID)
	// GetRecord Read one record
	// (GET /records/{recordId})
	GetRecord(w http.ResponseWriter, r *http.Request, recordId RecordID)
	// UpdateRecord Change a record
	// (PATCH /records/{recordId})
	UpdateRecord(w http.ResponseWriter, r *http.Request, recordId RecordID)
	// MakeRecordCanonical Make this the name an address reverses to
	// (POST /records/{recordId}/canonical)
	MakeRecordCanonical(w http.ResponseWriter, r *http.Request, recordId RecordID)
	// DetachRecord Take over a generated record
	// (POST /records/{recordId}/detach)
	DetachRecord(w http.ResponseWriter, r *http.Request, recordId RecordID)
	// GetSecondaryConfig Write the configuration a secondary needs
	// (GET /secondary-config)
	GetSecondaryConfig(w http.ResponseWriter, r *http.Request, params GetSecondaryConfigParams)
	// GetSecondaryStatus Say what each secondary holds
	// (GET /secondary-status)
	GetSecondaryStatus(w http.ResponseWriter, r *http.Request)
	// GetSettings Read the server-wide settings
	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Change the server-wide settings
	// (PATCH /settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)
	// ListTokens List the tokens that may use this API
	// (GET /tokens)
	ListTokens(w http.ResponseWriter, r *http.Request)
	// CreateToken Mint a token
	// (POST /tokens)
	CreateToken(w http.ResponseWriter, r *http.Request)
	// RevokeToken Withdraw a token
	// (DELETE /tokens/{tokenId})
	RevokeToken(w http.ResponseWriter, r *http.Request, tokenId string)
	// ListTSIGKeys List the keys a secondary may sign a transfer with
	// (GET /tsig-keys)
	ListTSIGKeys(w http.ResponseWriter, r *http.Request)
	// CreateTSIGKey Create a key
	// (POST /tsig-keys)
	CreateTSIGKey(w http.ResponseWriter, r *http.Request)
	// RevokeTSIGKey Withdraw a key
	// (DELETE /tsig-keys/{keyId})
	RevokeTSIGKey(w http.ResponseWriter, r *http.Request, keyId string)
	// ReadTSIGKeySecret Read a key's secret
	// (GET /tsig-keys/{keyId}/secret)
	ReadTSIGKeySecret(w http.ResponseWriter, r *http.Request, keyId string)
	// ListZones List zones
	// (GET /zones)
	ListZones(w http.ResponseWriter, r *http.Request, params ListZonesParams)
	// CreateZone Create a zone
	// (POST /zones)
	CreateZone(w http.ResponseWriter, r *http.Request)
	// ImportZone Bring a whole zone in from a zonefile
	// (POST /zones/import)
	ImportZone(w http.ResponseWriter, r *http.Request, params ImportZoneParams)
	// DeleteZone Delete a zone and everything in it
	// (DELETE /zones/{zoneId})
	DeleteZone(w http.ResponseWriter, r *http.Request, zoneId ZoneID)
	// GetZone Read one zone
	// (GET /zones/{zoneId})
	GetZone(w http.ResponseWriter, r *http.Request, zoneId ZoneID)
	// UpdateZone Change a zone's own settings
	// (PATCH /zones/{zoneId})
	UpdateZone(w http.ResponseWriter, r *http.Request, zoneId ZoneID)
	// CheckZone Report what is wrong with a zone as it stands
	// (GET /zones/{zoneId}/check)
	CheckZone(w http.ResponseWriter, r *http.Request, zoneId ZoneID, params CheckZoneParams)
	// ExportZone Write a zone out as a zonefile
	// (GET /zones/{zoneId}/export)
	ExportZone(w http.ResponseWriter, r *http.Request, zoneId ZoneID)
	// ReconcileZone Write the reverse entries this zone's records imply and does not have
	// (POST /zones/{zoneId}/reconcile)
	ReconcileZone(w http.ResponseWriter, r *http.Request, zoneId ZoneID)
	// ListRecords List the records of a zone
	// (GET /zones/{zoneId}/records)
	ListRecords(w http.ResponseWriter, r *http.Request, zoneId ZoneID, params ListRecordsParams)
	// CreateRecord Add a record to a zone
	// (POST /zones/{zoneId}/records)
	CreateRecord(w http.ResponseWriter, r *http.Request, zoneId ZoneID)
	// RollbackZone Restore a zone to the state it had at a serial
	// (POST /zones/{zoneId}/rollback)
	RollbackZone(w http.ResponseWriter, r *http.Request, zoneId ZoneID)
	// ReplaceRRsets Make the named RRsets exactly what is given
	// (PUT /zones/{zoneId}/rrsets)
	ReplaceRRsets(w http.ResponseWriter, r *http.Request, zoneId ZoneID)
}

